/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen1Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffsetMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // Logic: hoursInMinutes = -300. minutesOffset = -300 - 30 = -330.
        // -330 * 60000 = -19800000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffsetMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset_ZeroMinutes() {
        // Test -5:00
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 0);
        int expectedOffsetMillis = (-5 * 60) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryHoursLow() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, 0);
        int expectedOffsetMillis = (-23 * 60) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryHoursHigh() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int expectedOffsetMillis = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryMinutes() {
        // Test 0 minutes
        DateTimeZone zone0 = DateTimeZone.forOffsetHoursMinutes(1, 0);
        assertEquals(1 * 60 * DateTimeConstants.MILLIS_PER_MINUTE, zone0.getOffset(0));

        // Test 59 minutes
        DateTimeZone zone59 = DateTimeZone.forOffsetHoursMinutes(1, 59);
        assertEquals((1 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE, zone59.getOffset(0));
    }
}
